    65  static uint transformFromMsDos(const char *buffer)
    66  {
    67      quint16 time = (uchar)buffer[0] | ((uchar)buffer[1] << 8);
    68      int h = time >> 11;
    69      int m = (time & 0x7ff) >> 5;
    70      int s = (time & 0x1f) * 2;
    71      QTime qt(h, m, s);
    72
    73      quint16 date = (uchar)buffer[2] | ((uchar)buffer[3] << 8);
    74      int y = (date >> 9) + 1980;
    75      int o = (date & 0x1ff) >> 5;
    76      int d = (date & 0x1f);
    77      QDate qd(y, o, d);
    78
    79      QDateTime dt(qd, qt);
    80      return dt.toTime_t();
    81  }
