  1010      //qCDebug(KArchiveLog) << "end : centraldirsize: " << cdsize;
  1011
  1012      buffer[16] = char(centraldiroffset); // central dir offset
  1013      buffer[17] = char(centraldiroffset >> 8);
  1014      buffer[18] = char(centraldiroffset >> 16);
  1015      buffer[19] = char(centraldiroffset >> 24);
  1016
  1017      buffer[20] = 0; //zipfile comment length
  1018      buffer[21] = 0;
  1019
  1020      if (device()->write(buffer, 22) != 22) {
  1021          setErrorString(
  1022              tr("Could not write central dir record: %1")
  1023              .arg(device()->errorString()));
  1024          return false;
  1025      }
  1026
  1027      return true;
  1028  }
