  1030  bool KZip::doWriteDir(const QString &name, const QString &user, const QString &group, mode_t perm,
  1031                        const QDateTime &atime, const QDateTime &mtime, const QDateTime &ctime)
  1032  {
  1033      // Zip files have no explicit directories, they are implicitly created during extraction time
  1034      // when file entries have paths in them.
  1035      // However, to support empty directories, we must create a dummy file entry which ends with '/'.
  1036      QString dirName = name;
  1037      if (!name.endsWith(QLatin1Char('/'))) {
  1038          dirName = dirName.append(QLatin1Char('/'));
  1039      }
  1040      return writeFile(dirName, QByteArray(), perm, user, group, atime, mtime, ctime);
